{% extends "jusprin/v2/web/base.html" %}
{% load i18n %}
{% block content %}
<style>
.plans { display: flex; gap: 16px; align-items: stretch; }
.plans .card { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 16px; }
.plans .head { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.plans .head h2 { flex: 1 0 auto; white-space: nowrap; }
.plans .price { display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap; }
.plans .price .amount { font-size: 24px; line-height: 30px; font-weight: 700; }
.plans .grow { flex: 1 1 auto; }
.plans .foot { display: flex; flex-direction: column; gap: 12px; }
/* "Subscribe to Workshop yearly" is wider than a narrow card. */
.plans .foot .button.wide { white-space: normal; }
.costs { display: flex; gap: 16px; align-items: center; justify-content: space-between; flex-wrap: wrap; }
.seg { display: inline-flex; height: 30px; padding: 3px; border-radius: 4px; background: var(--surface-subtle);
  box-shadow: inset 0 0 0 1px var(--border-subtle); }
.seg a { display: flex; align-items: center; padding: 0 16px; border-radius: 4px; font-size: 12px; line-height: 16px;
  font-weight: 400; color: var(--text-primary); white-space: nowrap; }
.seg a:hover { text-decoration: none; background: var(--surface-selected); }
.seg a[aria-current] { background: var(--action-primary); color: var(--action-on-primary); }
@media (max-width: 720px) { .plans { flex-direction: column; } }
</style>
{% if launch %}{% include "jusprin/v2/web/launch_banner.html" %}{% endif %}
<div class="note">
  <p>{{ where.line }}</p>
  {% if where.billing %}<a href="{% url 'jusprin_v2_web_billing' %}">{% translate "Billing" %}</a>{% endif %}
</div>
<div class="costs">
  {% if message_prices %}<p class="secondary">{{ message_prices }}</p>{% endif %}
  <nav class="seg" aria-label="{% translate "Billing period" %}">
    <a href="?{% if guest %}guest=1&amp;{% endif %}period=month"{% if period == 'month' %} aria-current="page"{% endif %}>{% translate "Pay monthly" %}</a>
    <a href="?{% if guest %}guest=1&amp;{% endif %}period=year"{% if period == 'year' %} aria-current="page"{% endif %}>{% translate "Pay yearly" %}</a>
  </nav>
</div>
<div class="plans">
  {% for card in cards %}
  <section class="card" aria-label="{{ card.name }}">
    <div class="head">
      <h2>{{ card.name }}</h2>
      {% if launch %}<span class="badge"><svg viewBox="0 0 24 24" width="12" height="12" aria-hidden="true"><path d="M12 2l1.8 6.2L20 10l-6.2 1.8L12 18l-1.8-6.2L4 10l6.2-1.8z"/></svg>{% translate "2× launch bonus" %}</span>{% endif %}
    </div>
    <div class="price">
      {% if card.was %}<s class="small">{{ card.was }}</s>{% endif %}
      <span class="amount">{{ card.price }}</span>
      <span class="small secondary">{{ card.per }}</span>
    </div>
    {% if card.discount %}<p class="small" style="color:var(--status-success)">{{ card.discount }}</p>{% endif %}
    {% if card.saving %}<p class="small secondary">{{ card.saving }}</p>{% endif %}
    {% if card.credits_line %}<p class="bold">{{ card.credits_line }}</p>
    {% else %}<p class="bold">{% if launch %}<s>{{ card.credits.usual }}</s> {% endif %}{{ card.credits.now }}</p>{% endif %}
    <div class="grow"></div>
    <div class="foot">
      <p class="small">{{ card.note }}</p>
      {% if not signed_in %}
        <a class="button wide" href="{% url 'jusprin_v2_web_done' %}">{% translate "Sign up to buy" %}</a>
      {% elif card.current %}
        <button class="button wide" type="button" disabled>{% translate "Your plan" %}</button>
      {% else %}
        <form method="post" action="{% url 'jusprin_v2_web_checkout' %}">
          {% csrf_token %}
          <input type="hidden" name="what" value="{{ card.id }}">
          <button class="button primary wide" type="submit">{{ card.verb }}</button>
        </form>
      {% endif %}
    </div>
  </section>
  {% endfor %}
</div>
<p class="small secondary">{% blocktranslate count free_credits=free_credits %}After your first month, accounts without a plan get {{ free_credits }} free credit a month. Your own API key stays free and never uses credits.{% plural %}After your first month, accounts without a plan get {{ free_credits }} free credits a month. Your own API key stays free and never uses credits.{% endblocktranslate %}</p>
{% endblock %}
